// مثال 2: الحلقة الخارجية تتضاعف هندسياً والداخلية خطية -> O(n) مفاجئة!
// المجموع: 1 + 2 + 4 + 8 + ... + n = 2n - 1 -> O(n)
fun geometricLoop(n: Int) {
    var count = 0
    var i = 1
    while (i <= n) {
        for (j in 0 until i) {
            count++
        }
        i *= 2 // تضاعف هندسي
    }
}
