PAT-01.worked_example_ar:
في الـ Architecture، بنحدد الـ Boundary بين الـ Domain والـ Data:
```kotlin
// 1. Architecture: Domain Interface بتعزل قواعد الشغل عن أي SDK خارجي
interface CheckoutRepository {
    suspend fun pay(orderId: String, amountCents: Long): Result<PaymentConfirmation>
}

// 2. Design Pattern: Strategy محلي جوه Data Layer للتعامل مع الـ Gateways
interface PaymentGatewayStrategy {
    suspend fun execute(amountCents: Long): GatewayResult
}

class StripeGatewayStrategy(private val api: StripeApi) : PaymentGatewayStrategy {
    override suspend fun execute(amountCents: Long): GatewayResult = runCatching {
        api.createCharge(amountCents)
    }.fold(onSuccess = { GatewayResult.Success(it.id) }, onFailure = { GatewayResult.Failed(it.message) })
}

// الـ Repository في Data Layer بتطبق الـ Architecture Contract وتستخدم الـ Strategy
class CheckoutRepositoryImpl(
    private val strategies: Map<String, PaymentGatewayStrategy>
) : CheckoutRepository {
    override suspend fun pay(orderId: String, amountCents: Long): Result<PaymentConfirmation> {
        val strategy = strategies["stripe"] ?: return Result.failure(IllegalStateException("Gateway missing"))
        return when (val result = strategy.execute(amountCents)) {
            is GatewayResult.Success -> Result.success(PaymentConfirmation(orderId, result.txId))
            is GatewayResult.Failed -> Result.failure(Exception(result.error))
        }
    }
}
```

